-- Converted: grantee operator -> ROLE OPERATOR; sales.payment -> SALES.PAYMENT.
-- Reason: Snowflake grants object privileges to roles, so the grantee must be named with the ROLE keyword; privileges and object type are unchanged.
GRANT SELECT, INSERT ON TABLE SALES.PAYMENT TO ROLE OPERATOR;

-- Converted: grantee auditor -> ROLE AUDITOR; sales.audit_log -> SALES.AUDIT_LOG.
-- Reason: Snowflake grants object privileges to roles, so the grantee must be named with the ROLE keyword; privilege and object type are unchanged.
GRANT SELECT ON TABLE SALES.AUDIT_LOG TO ROLE AUDITOR;

-- Converted: GRANT EXECUTE PROCEDURE ON sales.add_payment TO operator -> GRANT USAGE ON PROCEDURE SALES.ADD_PAYMENT(NUMBER, NUMBER, NUMBER) TO ROLE OPERATOR.
-- Reason: Snowflake has no EXECUTE PROCEDURE privilege; calling a procedure requires USAGE, the procedure must be identified by ***MASKED*** argument type signature, and grantees are roles.
GRANT USAGE ON PROCEDURE SALES.ADD_PAYMENT(NUMBER, NUMBER, NUMBER) TO ROLE OPERATOR;

-- Converted: ON TABLE sales.customer_accounts -> ON VIEW SALES.CUSTOMER_ACCOUNTS; grantee reader -> ROLE READER.
-- Reason: SALES.CUSTOMER_ACCOUNTS is a view in Snowflake, so the object type in the grant is VIEW; Snowflake grants object privileges to roles, so the grantee is named with the ROLE keyword. The privilege is unchanged.
GRANT SELECT ON VIEW SALES.CUSTOMER_ACCOUNTS TO ROLE READER;

-- Converted: ON TABLE sales.account_payments -> ON VIEW SALES.ACCOUNT_PAYMENTS; grantee reader -> ROLE READER.
-- Reason: SALES.ACCOUNT_PAYMENTS is a view in Snowflake, so the object type in the grant is VIEW; Snowflake grants object privileges to roles, so the grantee is named with the ROLE keyword. The privilege is unchanged.
GRANT SELECT ON VIEW SALES.ACCOUNT_PAYMENTS TO ROLE READER;
